def _retailer_restock(self) -> None:
    if self.retailer is None:
        return
    # Apply supply shock
    shock_p = float(self.params.get("supply_shock_probability", 0.0))
    restock = int(self.retailer.restock_rate_daily)
    if self.rng.uniform() < shock_p:
        restock = int(restock * 0.2)  # 80% reduction under shock
    self.retailer.inventory += max(0, restock)
